1	import {
2		SANDBOX_PROVIDER_KEY_PREFIX,
3		SANDBOX_ROW_KEY_PREFIX,
4	} from "@lobu/core/reserved";
5	import type {
6		ConnectionFacets,
7		ConnectorDefinitionItem,
8	} from "@/lib/api/connections";
9	import type { SandboxItem } from "@/lib/api/sandboxes";
10	
11	/**
12	 * Remote sandboxes as connectors-list / catalog rows.
13	 *
14	 * Same shape as model-provider rows (`inference-rows.ts`): a sandbox is a
15	 * credential-backed thing you connect, so it belongs under Connectors. It is
16	 * NOT a `connections` row — sandboxes live in their own table. Read-layer
17	 * union only.
18	 *
19	 * Two key shapes:
20	 *  - `sandbox:{id}` — an org's sandbox instance (list + detail)
21	 *  - `sandbox-provider:{kind}` — a provider kind in the catalog (e.g. vercel).
22	 *    Picking it opens the create form locked to that kind — no second
23	 *    "which provider?" step.
24	 */
25	
26	export { SANDBOX_PROVIDER_KEY_PREFIX, SANDBOX_ROW_KEY_PREFIX };
27	
28	const RUNTIME_ONLY_FACETS: ConnectionFacets = {
29		data: false,
30		chat: false,
31		actions: false,
32		audience: false,
33		inference: false,
34		runtime: true,
35	};
36	
37	/** Human label for a runtime provider kind. */
38	export function sandboxProviderLabel(kind: string): string {
39		if (kind === "vercel") return "Vercel";
40		return kind.charAt(0).toUpperCase() + kind.slice(1);
41	}
42	
43	/**
44	 * Credential fields per provider kind. Mirrors the gateway runtime registry's
45	 * `credentialFields` until the list API surfaces them. v1: Vercel only.
46	 */
47	export const SANDBOX_PROVIDER_FIELDS: Record<
48		string,
49		{ key: string; label: string; secret?: boolean }[]
50	> = {
51		vercel: [
52			{ key: "token", label: "Access token", secret: true },
53			{ key: "teamId", label: "Team ID", secret: false },
54			{ key: "projectId", label: "Project ID", secret: false },
55		],
56	};
57	
58	export function parseSandboxRowKey(connectorKey: string): string | null {
59		if (!connectorKey.startsWith(SANDBOX_ROW_KEY_PREFIX)) return null;
60		const id = connectorKey.slice(SANDBOX_ROW_KEY_PREFIX.length);
61		return id.length > 0 ? id : null;
62	}
63	
64	export function parseSandboxProviderKey(connectorKey: string): string | null {
65		if (!connectorKey.startsWith(SANDBOX_PROVIDER_KEY_PREFIX)) return null;
66		const kind = connectorKey.slice(SANDBOX_PROVIDER_KEY_PREFIX.length);
67		return kind.length > 0 ? kind : null;
68	}
69	
70	/** True when the key is either a sandbox instance or a sandbox provider kind. */
71	export function isSandboxConnectorKey(connectorKey: string): boolean {
72		return (
73			parseSandboxRowKey(connectorKey) !== null ||
74			parseSandboxProviderKey(connectorKey) !== null
75		);
76	}
77	
78	export interface SandboxConnectorRow {
79		connector: ConnectorDefinitionItem;
80		facets: ConnectionFacets;
81		sandbox: SandboxItem;
82	}
83	
84	/**
85	 * Org sandbox instances as list rows. Built-in local runtime is omitted (not
86	 * a row you can disconnect).
87	 */
88	export function buildSandboxConnectorRows(
89		sandboxes: readonly SandboxItem[],
90	): SandboxConnectorRow[] {
91		return sandboxes.map((sandbox) => ({
92			sandbox,
93			facets: RUNTIME_ONLY_FACETS,
94			connector: {
95				key: `${SANDBOX_ROW_KEY_PREFIX}${sandbox.id}`,
96				name: sandbox.name || sandboxProviderLabel(sandbox.providerKind),
97				description: null,
98				version: "",
99				auth_schema: null,
100				feeds_schema: null,
101				actions_schema: null,
102				options_schema: null,
103				status: sandbox.connected ? "active" : "error",
104				login_enabled: false,
105				installed: true,
106			} as ConnectorDefinitionItem,
107		}));
108	}
109	
110	/**
111	 * Catalog entries for each connectable runtime provider kind. These are the
112	 * "kinds" you pick under Add connector — same place as Slack/GitHub, filtered
113	 * by the Runtime chip. Selecting one routes to the locked create form.
114	 */
115	export function buildSandboxProviderCatalogEntries(
116		availableProviders: readonly string[],
117	): ConnectorDefinitionItem[] {
118		return availableProviders.map(
119			(kind) =>
120				({
121					key: `${SANDBOX_PROVIDER_KEY_PREFIX}${kind}`,
122					name: sandboxProviderLabel(kind),
123					description: `Run agents in a ${sandboxProviderLabel(kind)} sandbox instead of the built-in local runtime.`,
124					version: "",
125					auth_schema: null,
126					feeds_schema: null,
127					actions_schema: null,
128					options_schema: null,
129					status: "active",
130					login_enabled: false,
131					// Catalog entry, not yet an org sandbox instance.
132					installed: false,
133					installable: false,
134				}) as ConnectorDefinitionItem,
135		);
136	}
137	
138	export function sandboxCatalogFacets(): ConnectionFacets {
139		return RUNTIME_ONLY_FACETS;
140	}
