function SandboxProviderConnectBody({
	ownerSlug,
	providerKind,
}: {
	ownerSlug: string;
	providerKind: string;
}) {
	const navigate = useNavigate();
	const createSandbox = useCreateSandbox();
	const { data, isLoading } = useSandboxes();
	const available = data?.availableProviders ?? [];
	const known = available.includes(providerKind) || available.length === 0;
	const label = sandboxProviderLabel(providerKind);

	if (isLoading) {
		return (
			<div className="mx-auto w-full max-w-3xl space-y-4">
				<div className="flex items-center gap-2">
					<Skeleton className="h-6 w-6 rounded" />
					<Skeleton className="h-5 w-40" />
				</div>
				<Skeleton className="h-24 w-full rounded-lg" />
			</div>
		);
	}

	if (!known && available.length > 0) {
		return (
			<div className="mx-auto w-full max-w-3xl space-y-3">
				<p className="text-sm text-muted-foreground">
					Unknown sandbox provider <strong>{providerKind}</strong>. Available:{" "}
					{available.map(sandboxProviderLabel).join(", ")}.
				</p>
				<Button
					variant="outline"
					size="sm"
					onClick={() =>
						void navigate({
							to: "/$owner/connectors",
							params: { owner: ownerSlug },
						})
					}
				>
					Back to connectors
				</Button>
			</div>
		);
	}

	return (
		<div className="mx-auto w-full max-w-3xl space-y-6">
			<DetailHeader
				breadcrumb={
					<DetailBreadcrumb
						crumbs={[
							<Link
								key="connectors"
								to="/$owner/connectors"
								params={{ owner: ownerSlug }}
								className={DETAIL_CRUMB_LINK_CLASS}
							>
								Connectors
							</Link>,
						]}
					/>
				}
				icon={
					<span className="flex h-8 w-8 items-center justify-center rounded-md bg-muted text-muted-foreground">
						<Plug className="h-4 w-4" />
					</span>
				}
				title={label}
				status={<FacetChips facets={RUNTIME_ONLY_FACETS} />}
			/>
			<div className="rounded-lg border p-4">
				<CreateSandboxForm
					providerKind={providerKind}
					pending={createSandbox.isPending}
					onCancel={() =>
						void navigate({
							to: "/$owner/connectors/create",
							params: { owner: ownerSlug },
						})
					}
					onCreate={(payload) =>
						createSandbox.mutate(payload, {
							onSuccess: (result) => {
								const id = result?.sandbox?.id;
								if (id) {
									void navigate({
										to: "/$owner/connectors/$connectorKey",
										params: {
											owner: ownerSlug,
											connectorKey: `sandbox:${id}`,
										},
									});
									return;
								}
								void navigate({
									to: "/$owner/connectors",
									params: { owner: ownerSlug },
								});
							},
						})
					}
				/>
			</div>
		</div>
	);
}

