50	): { error: string } | null {
51		const provider = getGatewayRuntimeProvider(providerKind);
52		if (!provider) return { error: `Unknown runtime provider: ${providerKind}` };
53	
54		const fieldByKey = new Map(provider.credentialFields.map((f) => [f.key, f]));
55		for (const key of Object.keys(credential)) {
56			if (!fieldByKey.has(key)) {
57				return { error: `Unknown credential field for ${providerKind}: ${key}` };
