import type { AgentTab } from "@/components/agents/agents-workbench";
import { agentChatLink } from "@/lib/agent-chat-routes";

export function agentTabLink(
	owner: string,
	agentId: string,
	tab: AgentTab,
): { to: string; params: Record<string, string> } {
	if (tab === "chat") {
		return { ...agentChatLink(owner, agentId) };
	}
	if (tab === "behaviors") {
		return {
			to: "/$owner/agents/$agentId/behaviors",
			params: { owner, agentId },
		};
	}
	if (tab === "skills") {
		return {
			to: "/$owner/agents/$agentId/skills",
			params: { owner, agentId },
		};
	}
	if (tab === "guardrails") {
		return {
			to: "/$owner/agents/$agentId/guardrails",
			params: { owner, agentId },
		};
	}
	if (tab === "identity") {
		return {
			to: "/$owner/agents/$agentId/identity",
			params: { owner, agentId },
		};
	}
	return {
		to: "/$owner/agents/$agentId/settings",
		params: { owner, agentId },
	};
}

