157	 * Returns `current` unchanged when nothing rendered differs. That bail-out is
158	 * load bearing: the hook hands back a brand-new graph object every render (its
159	 * `rulesBySlug` comes from `useQueries`' combine), so a resync that always
160	 * produced a new array would be an infinite setState/render loop.
161	 *
162	 * Everything except position is compared, rather than a hand-listed subset —
163	 * a whitelist silently goes stale the moment a field is added to the node, and
164	 * has already caused renamed types and refreshed counts to keep displaying old
165	 * values.
166	 */
167	function mergeGraphIntoNodes(
168		current: SchemaFlowNode[],
169		next: SchemaFlowNode[],
170	): SchemaFlowNode[] {
171		const byId = new Map(current.map((node) => [node.id, node]));
172		let changed = current.length !== next.length;
173	
174		const merged = next.map((node, index) => {
175			const existing = byId.get(node.id);
176			if (!existing || current[index]?.id !== node.id) {
177				changed = true;
178				return node;
179			}
180			// Keep where the user put it; take everything else from the rebuild.
181			const candidate: SchemaFlowNode = { ...node, position: existing.position };
182			if (renderedStateOf(existing) === renderedStateOf(candidate)) return existing;
183			changed = true;
184			return candidate;
185		});
186	
187		return changed ? merged : current;
188	}
