/**
 * Collapse override for a route-driven collapsible: the route decides the
 * default (active ⇒ open), a manual toggle wins until the route context
 * changes again. Implemented with the render-time state-reset idiom so a
 * navigation into/out of the group re-applies the route default.
 */
function useRouteDefaultOpen(routeActive: boolean): {
	open: boolean;
	setOpen: (open: boolean) => void;
} {
	const [override, setOverride] = useState<boolean | null>(null);
	const [lastRouteActive, setLastRouteActive] = useState(routeActive);
	if (routeActive !== lastRouteActive) {
		setLastRouteActive(routeActive);
		setOverride(null);
	}
	return { open: override ?? routeActive, setOpen: setOverride };
}

/** Chevron glyph for a collapsible nav group (label the wrapping button). */
function GroupChevron({ open }: { open: boolean }) {
	return (
		<span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/40 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground">
			<ChevronRight
				className={cn(
					"h-3.5 w-3.5 transition-transform",
					open ? "rotate-90" : "rotate-0",
				)}
			/>
		</span>
	);
}

/** Deterministic initials for an agent's avatar glyph. */
function agentInitial(name: string): string {
	return name.trim().charAt(0).toUpperCase() || "?";
}

/**
 * Per-agent sub-pages in the sidebar. Chat is the agent row itself.
 *
 * The split is by KIND, not by count: what you work with (Behaviors, Skills)
 * is a sidebar destination; what you configure once (Identity, Guardrails,
 * Permissions, and the settings proper) stays behind the single Settings row
 * and keeps its tab strip there. Promoting all seven would make every agent a
 * seven-row tree and give one-time config the same weight as daily work.
 */
const AGENT_CHILD_ROWS = [
	{
		key: "behaviors",
		label: "Behaviors",
		icon: ListChecks,
		subpath: "behaviors",

	ownerSlug: string;
	agentId: string;
	name: string;
	status: "active" | "idle";
	selected: boolean;
	pathname: string;
}) {
	const working = status === "active";
	const chat = agentChatLink(ownerSlug, agentId);
	const base = `/${ownerSlug}/agents/${agentId}`;
	const { open, setOpen } = useRouteDefaultOpen(selected);
	const activeChildKey = AGENT_CHILD_ROWS.find((child) =>
		pathname.startsWith(`${base}/${child.subpath}`),
	)?.key;

	return (
		<Collapsible open={open} onOpenChange={setOpen}>
			<div
				className={cn(
					"mx-2 flex items-center gap-2 rounded-md py-1.5 pl-3 pr-2 text-sm transition-colors",
					// On chat (or any sub-page without a child), the agent row is
					// the active highlight. On a listed config route the child takes it.
					selected && !(open && activeChildKey)
						? "bg-sidebar-accent text-sidebar-accent-foreground"
						: "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
				)}
			>
				<Link
					to={chat.to}
					params={chat.params}
					className="flex min-w-0 flex-1 items-center gap-2"
				>
					<span className="relative flex h-[18px] w-[18px] shrink-0 items-center justify-center rounded-full bg-sidebar-accent text-[9px] font-semibold text-sidebar-accent-foreground">
						{agentInitial(name)}
						<span
							className={cn(
								"absolute -bottom-0.5 -right-0.5 h-[7px] w-[7px] rounded-full border-[1.5px] border-sidebar-background",
								working ? "bg-emerald-500" : "bg-sidebar-foreground/30",
							)}
						/>
					</span>
					<span className="min-w-0 flex-1 truncate">{name}</span>
					{working ? (
						<span className="shrink-0 text-[10px] text-sidebar-foreground/40">
							working
						</span>
					) : null}
				</Link>
				<CollapsibleTrigger asChild>
					<button
						type="button"
						aria-label={open ? `Collapse ${name}` : `Expand ${name}`}
						title={open ? `Collapse ${name}` : `Expand ${name}`}
						className="shrink-0"
					>
						<GroupChevron open={open} />
					</button>
				</CollapsibleTrigger>
			</div>
			<CollapsibleContent>
				{AGENT_CHILD_ROWS.map((child) => (
					<NavRow
						key={child.key}
						to={`/$owner/agents/$agentId/${child.subpath}`}
						params={{ owner: ownerSlug, agentId }}
						active={activeChildKey === child.key}
						icon={child.icon}
						label={child.label}
						indent
					/>
				))}
			</CollapsibleContent>
		</Collapsible>
	);
}

