/**
 * E2E: drive the REAL /internal/runtime/exec route with a REAL signed worker
 * token, so provider.exec() runs against a live Vercel Sandbox.
 *
 * Uses generateWorkerToken (the same function the runs-queue dispatcher uses)
 * rather than hand-rolling a JWT — the egress allow/deny lists and the provider
 * id are read from the SIGNED claims, so a hand-rolled token would not exercise
 * the real contract.
 */
import { generateWorkerToken } from "@lobu/core";

const GATEWAY = process.env.GATEWAY ?? "http://127.0.0.1:9061";
const ORG = process.env.ORG_ID;
const AGENT = process.env.AGENT_ID ?? "lobu-builder";
const CONV = process.env.CONV_ID ?? "e2e-runtime-conv";
const SANDBOX_ID = process.env.SANDBOX_ID || undefined;
const COMMAND = process.env.COMMAND ?? "uname -a; echo LOBU_E2E_OK";
const ALLOWED = (process.env.ALLOWED_DOMAINS ?? "example.com")
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);

if (!ORG) {
  console.error("ORG_ID is required");
  process.exit(1);
}

const token = generateWorkerToken(
  process.env.USER_ID ?? "e2e-user",
  CONV,
  process.env.DEPLOYMENT ?? "e2e-deployment",
  {
    channelId: "e2e-channel",
    agentId: AGENT,
    organizationId: ORG,
    runtimeProviderId: "vercel",
    sandboxId: SANDBOX_ID,
    allowedDomains: ALLOWED,
    deniedDomains: [],
  },
);

console.log(
  JSON.stringify({
    step: "token-minted",
    sandboxBound: Boolean(SANDBOX_ID),
    allowedDomains: ALLOWED,
  }),
);

const started = Date.now();
const res = await fetch(`${GATEWAY}/lobu/internal/runtime/exec`, {
  method: "POST",
  headers: {
    authorization: `Bearer ${token}`,
    "content-type": "application/json",
  },
  body: JSON.stringify({ command: COMMAND, timeoutMs: 120_000 }),
});

const text = await res.text();
let parsed;
try {
  parsed = JSON.parse(text);
} catch {
  parsed = { raw: text.slice(0, 800) };
}

console.log(
  JSON.stringify(
    {
      step: "exec-response",
      status: res.status,
      elapsedMs: Date.now() - started,
      ...parsed,
    },
    null,
    2,
  ),
);

process.exit(res.status === 200 ? 0 : 1);

