/**
 * SCRATCH E2E — not for commit.
 *
 * Every existing contributed-CLI test uses a FIXTURE binary under the
 * unsandboxed opt-in, because neither real sandbox can see a fake CLI in a temp
 * dir. This drives the real `gh`/`git` already on this host through a REAL
 * sandbox-exec strategy, which is the production posture and the one
 * combination nothing covers.
 */
import { describe, expect, test } from "bun:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { probeSandboxStrategy } from "../embedded/exec-sandbox";
import { createEmbeddedBashOps } from "../embedded/just-bash-bootstrap";

async function runWith(
  nixPackages: string | undefined,
  command: string
): Promise<{ exitCode: number; output: string }> {
  const workspace = fs.realpathSync(
    fs.mkdtempSync(path.join(os.tmpdir(), "gh-e2e-"))
  );
  if (nixPackages === undefined) delete process.env.NIX_PACKAGES;
  else process.env.NIX_PACKAGES = nixPackages;
  delete process.env.LOBU_WORKSPACE_BACKEND;
  delete process.env.LOBU_ALLOW_UNSANDBOXED_EXEC;
  delete process.env.LOBU_EXEC_SANDBOX;

  const ops = await createEmbeddedBashOps({ workspaceDir: workspace });
  const chunks: string[] = [];
  const result = await ops.exec(command, "/", {
    onData: (c: Buffer | string) => chunks.push(c.toString()),
    timeout: 20,
  });
  fs.rmSync(workspace, { recursive: true, force: true });
  return { exitCode: result.exitCode, output: chunks.join("") };
}

describe("real gh under a real sandbox", () => {
  test("sandbox is genuinely active on this host", () => {
    const strategy = probeSandboxStrategy();
    console.log("STRATEGY:", JSON.stringify(strategy));
    expect(strategy.kind).not.toBe("none");
  });

  test("DECLARED gh runs (the headline claim)", async () => {
    const r = await runWith("gh", "gh --version");
    console.log("declared-gh:", r.exitCode, r.output.trim().split("\n")[0]);
    expect(r.exitCode).toBe(0);
    expect(r.output).toContain("gh version");
  });

  test("DECLARED git runs", async () => {
    const r = await runWith("git", "git --version");
    console.log("declared-git:", r.exitCode, r.output.trim().split("\n")[0]);
    expect(r.exitCode).toBe(0);
    expect(r.output).toContain("git version");
  });

  test("UNDECLARED gh stays unavailable (declaration is what widens)", async () => {
    const r = await runWith(undefined, "gh --version");
    console.log("undeclared-gh:", r.exitCode, r.output.trim().split("\n")[0]);
    expect(r.exitCode).not.toBe(0);
  });

  test("UNDECLARED curl on PATH stays unavailable", async () => {
    const r = await runWith("gh", "curl --version");
    console.log("undeclared-curl:", r.exitCode, r.output.trim().split("\n")[0]);
    expect(r.exitCode).not.toBe(0);
  });

  test("declared interpreter stays blocked without the per-agent opt-in", async () => {
    const r = await runWith("nodejs", "node --version");
    console.log("declared-node:", r.exitCode, r.output.trim().split("\n")[0]);
    expect(r.exitCode).not.toBe(0);
  });
});

