const sandboxStrategy = probeSandboxStrategy();

// Registration is gated on ISOLATION, which has two independent sources:
// a real per-exec sandbox, or a deployment that hosts a single tenant.
//
// The container hosts every worker and the gateway as the same user, so a
// shell-capable CLI (gh runs extensions and aliases) can read sibling
// `workspaces/{agentId}` directories and /proc/1/environ — reproduced: a
// registered tool read another tenant's workspace file. What makes that a
// breach is the SIBLING, not the missing sandbox. A single-tenant deployment
// has no sibling to leak to, so the sandbox is not load-bearing there.
//
// Gating on the probe alone got this wrong in both directions: it denied
// single-tenant deployments a working CLI for no security benefit, and it
// would have permitted registration on any multi-tenant host where bwrap
// happened to start. Tenancy is a property of the deployment and cannot be
// inferred from a syscall, so it is declared.
//
// Defaults to multi-tenant: an operator who has not thought about it gets
// the safe answer.
const isolation = resolveWorkerIsolation();
const registerSpawnedBinaries = isolation.isolated;

/**
 * Why a spawned binary may be registered at all.
 *
 * `sandbox`  — a real per-exec sandbox (bwrap / sandbox-exec) confines it.
 * `single-tenant` — the deployment declares it hosts one tenant, so there is
 *   no sibling workspace to read. The operator asserts this; it is never
 *   inferred, because nothing observable from inside the container
 *   distinguishes "one tenant" from "one tenant so far".
 * `unsandboxed-opt-in` — the pre-existing escape hatch for trusted agents.
 */
export interface WorkerIsolation {
  isolated: boolean;
  reason: "sandbox" | "single-tenant" | "unsandboxed-opt-in" | "none";
}

/**
 * Resolve whether this worker is isolated enough to run spawned binaries.
 *
 * Order matters only for reporting — any one source is sufficient. The default
 * is NOT isolated: a deployment that declares nothing is treated as
 * multi-tenant, so the unsafe case is the one an operator has to opt into
 * rather than the one they get by forgetting.
 */
export function resolveWorkerIsolation(): WorkerIsolation {
  if (probeSandboxStrategy().kind !== "none") {
    return { isolated: true, reason: "sandbox" };
  }
  // Deployment-level assertion. Named for what it claims about the DEPLOYMENT,
  // not for what it unlocks, so it cannot read as a feature flag.
  const tenancy = (process.env.LOBU_DEPLOYMENT_TENANCY || "").toLowerCase();
  if (tenancy === "single") {
    return { isolated: true, reason: "single-tenant" };
  }
  if (
    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "1" ||
    process.env.LOBU_ALLOW_UNSANDBOXED_EXEC === "true"
  ) {
    return { isolated: true, reason: "unsandboxed-opt-in" };
  }
  return { isolated: false, reason: "none" };
}

/**
 * Binaries that are full code-execution capabilities. If they land on the
 * just-bash allowlist, the depth/loop caps are moot — the agent can run
 * arbitrary code through them. They are excluded by default; an agent that
 * genuinely needs them must opt in via
 * `LOBU_ALLOW_UNSANDBOXED_EXEC=1` (set per-agent in lobu.config.ts).
 */

