  console.log(`${leaked ? "LEAKED  " : "blocked "} ${JSON.stringify(cmd)} => ${JSON.stringify(out.slice(0, 80))}`);
}

fs.rmSync(workspace, { recursive: true, force: true });

const anyLeak = dump.includes("LEAK") || leakGrep.includes("LEAK");
console.log(`\n=== RESULT: ${anyLeak ? "LEAK DETECTED" : "NO LEAK"} ===`);

