export const meta = {
  name: 'conversation-read-path-audit',
  description: 'Root-cause empty conversation messages + missing Recent, and propose consolidation',
  phases: [
    { title: 'Investigate', detail: 'parallel readers over read path, list path, write path, agent context' },
    { title: 'Verify', detail: 'adversarially confirm each finding against source' },
    { title: 'Synthesize', detail: 'consolidated gaps + simplification proposal' },
  ],
}

const ROOT = '/Users/burakemre/Code/lobu/.claude/worktrees/nix-packages-allowlist'

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'number' },
          evidence: { type: 'string', description: 'exact code quoted from the file' },
          why_it_breaks: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
        },
        required: ['title', 'file', 'evidence', 'why_it_breaks', 'severity'],
      },
    },
  },
  required: ['findings'],
}

const FACTS = `
GROUND TRUTH measured against PRODUCTION (app.lobu.ai, org lobu-team, agent lobu-builder) minutes ago:

- GET /lobu/api/v1/agents/lobu-builder/conversations/<cid>/messages returns HTTP 200 with ZERO messages.
- The transcript DOES exist: agent_transcript_snapshot has the row for conversation
  "REDACTED",
  run_id 784077, byte_size 22420, terminal_status 'completed'.
- 42 snapshots exist for this agent+org, and 42/42 have a MATCHING conversations row
  (joined on conversation_id + organization_id). Nothing is orphaned.
- conversations rows are kind='owned', archived_at IS NULL, last_activity_at set correctly.
- The user also reports the "Recent" list in the UI shows nothing.
- Known readers of agent_transcript_snapshot: routes/public/agent-history.ts:56,
  services/agent-thread-list.ts:175 and :261, services/watcher-run-thread.ts:96.
- chat-response-bridge.ts:578 DELETEs from agent_transcript_snapshot on session reset.
- Separately: the agent does NOT know its own conversation id. Asked directly in
  production it answered "I DO NOT KNOW". No conversationId appears in
  agent-worker/src/runtime/session-context.ts and no conversation URL is built in the worker.
- The web route is /$owner/agents/$agentId/conversations/$conversationId.
`

const LENSES = [
  {
    key: 'messages-read',
    prompt: `In ${ROOT}, find the route that serves conversation MESSAGES and explain why it returns zero.

${FACTS}

Find the handler for GET .../agents/:agentId/conversations/:conversationId/messages (search packages/server/src/lobu/*.ts and packages/server/src/gateway/routes/**). Read its query. Then compare against what actually persists.

CRITICAL QUESTIONS: (1) Does it read agent_transcript_snapshot, or a different table/column that is empty? (2) Are there TWO storage paths for chat history (e.g. a live/streaming store vs the per-run snapshot) with the read hitting the wrong one? (3) Does the query filter on something (kind, platform, archived_at, user_id, run terminal_status) that excludes these rows? (4) Is the conversation_id it matches on a different form than what is stored (prefixed, hashed, sanitized)?

Quote exact code with line numbers. Name the precise reason the result is empty.`,
  },
  {
    key: 'recent-list',
    prompt: `In ${ROOT}, find what powers the "Recent" conversations list and why it renders nothing.

${FACTS}

Read packages/server/src/gateway/services/agent-thread-list.ts fully (note the comment at :175 about a "DISTINCT ON (conversation_id) FROM agent_transcript_snapshot derive path" — is that path live or dead?). Find the route that exposes it and the owletto component that consumes it.

CRITICAL QUESTIONS: (1) Does the list read `conversations` or derive from snapshots — and if both, which wins? (2) What filters could exclude kind='owned' rows, or rows whose platform is 'web'/'api'? (3) Does the frontend call a different endpoint than the one that works? (4) Is there an org-slug vs org-id mismatch in the route params?

Quote exact code with line numbers.`,
  },
  {
    key: 'write-path',
    prompt: `In ${ROOT}, trace what a chat turn WRITES for history, and find any dual-write divergence.

${FACTS}

Follow a turn from the gateway through to persistence: message-consumer.ts (note :417 mentions the per-run agent_transcript_snapshot POST), chat-response-bridge.ts, and whatever writes the conversations row.

CRITICAL QUESTIONS: (1) Is there a live dual-write (one store for streaming, one for durable history) and do they agree? (2) chat-response-bridge.ts:578 DELETEs snapshots on "session reset" — could a normal turn trigger that and wipe history? (3) Does anything write per-MESSAGE rows at all, or is the snapshot the ONLY durable record? (4) If the snapshot is the only record, what is the intended read path for it?

This determines whether the fix is a read fix or a missing write. Quote exact code.`,
  },
  {
    key: 'agent-context',
    prompt: `In ${ROOT}, determine exactly what identity/context an agent receives, and what it would take to tell it its own conversation id and URL.

${FACTS}

Read packages/agent-worker/src/runtime/session-context.ts and session-runner.ts. Find where the system prompt / runtime context is assembled (look for buildMcpInstructions and LOBU_DEFAULT_IDENTITY).

CRITICAL QUESTIONS: (1) What IS injected into agent context today — enumerate it. (2) Where does the worker already HAVE the conversationId (worker token claims, GatewayParams)? (3) What is the single smallest seam where conversation id + a viewer URL could be injected, alongside the existing MCP instructions? (4) Is there a configured public base URL available worker-side to build such a URL (grep PUBLIC_WEB_URL, LOBU_URL, publicGatewayUrl)?

The user wants to DELETE a UI workaround if the agent can know its own URL. Report what exists and the minimal addition. Quote exact code.`,
  },
]

phase('Investigate')

const results = await pipeline(
  LENSES,
  (lens) => agent(lens.prompt, { label: `probe:${lens.key}`, phase: 'Investigate', schema: FINDINGS }),
  (res, lens) => {
    if (!res || !res.findings || res.findings.length === 0) return []
    return parallel(
      res.findings.map((f) => () =>
        agent(
          `Adversarially verify this claim about ${ROOT}. DEFAULT to refuted=true; accept only if you open the file and quote the code yourself.

CLAIM: ${f.title}
FILE: ${f.file}${f.line ? ':' + f.line : ''}
EVIDENCE OFFERED: ${f.evidence}
WHY IT SUPPOSEDLY BREAKS: ${f.why_it_breaks}

${FACTS}

A claim that is merely plausible, or that describes intended behaviour rather than a real defect, must be refuted. A claim that contradicts the measured ground truth above must be refuted. Report refuted=true/false with your own quoted evidence.`,
          {
            label: `verify:${lens.key}`,
            phase: 'Verify',
            schema: {
              type: 'object',
              properties: {
                refuted: { type: 'boolean' },
                own_evidence: { type: 'string' },
                note: { type: 'string' },
              },
              required: ['refuted', 'own_evidence'],
            },
          }
        ).then((v) => ({ ...f, lens: lens.key, verdict: v }))
      )
    )
  }
)

const all = results.flat().filter(Boolean)
const confirmed = all.filter((f) => f.verdict && f.verdict.refuted === false)
log(`${all.length} findings raised, ${confirmed.length} survived verification`)

phase('Synthesize')

const synthesis = await agent(
  `Consolidate a gap audit of Lobu's conversation history read path at ${ROOT}.

CONFIRMED FINDINGS (each independently verified against source):
${JSON.stringify(confirmed.map((f) => ({ title: f.title, file: f.file, line: f.line, evidence: f.evidence, why: f.why_it_breaks, severity: f.severity })), null, 2)}

${FACTS}

USER'S DIRECTION, stated explicitly: they want to SIMPLIFY and CONSOLIDATE, remove tech debt, and DELETE workarounds — not add layers. They rejected a "degraded[] side-channel" earlier as a bolt-on. They specifically asked whether a UI view can be DELETED if the agent knows its own conversation URL.

Produce, concretely and without filler:

1. ROOT CAUSE of the empty /messages response — one paragraph, naming the exact code.
2. ROOT CAUSE of the empty "Recent" list — one paragraph. Say explicitly whether it is the SAME cause or a different one.
3. RANKED gap list (blocker first). Merge duplicates ruthlessly. One-line fix direction each.
4. CONSOLIDATION PROPOSAL: the single coherent change that subsumes the most gaps. Be concrete about files and shape. State explicitly what gets DELETED, not only what is added. If two storage or read paths exist for the same data, say which one should win and which should be removed.
5. AGENT SELF-AWARENESS: the minimal seam to give an agent its conversation id + viewer URL, and precisely which UI workaround that would let the user delete. If it should NOT be deleted, say why.
6. What should NOT be built, and why.

Be specific and short.`,
  { label: 'synthesize', phase: 'Synthesize' }
)

return { confirmedCount: confirmed.length, totalRaised: all.length, synthesis }

